import type { Beat } from "./schema";

/** A run of consecutive beats whose keyframes and cameras are generated by one model call. */
export interface Chunk {
  beatIds: string[];
  /** Film time the chunk covers. Chunks tile the film: each starts where the previous one ends. */
  startSec: number;
  endSec: number;
}

export interface ChunkOptions {
  /** Longest run of beats generated in one call; longer runs of the same place are split evenly. */
  maxBeats: number;
  /** Most chunks (and so most parallel calls); extra chunks are merged into their neighbors. */
  maxChunks: number;
}

export const DEFAULT_CHUNK_OPTIONS: ChunkOptions = { maxBeats: 3, maxChunks: 6 };

/** "INT. SUBWAY STATION - NIGHT" and "Subway station" are the same place. */
export function placeKey(location: string): string {
  return location
    .toLowerCase()
    .replace(/^\s*(int\.?\/ext\.?|ext\.?\/int\.?|int\.?|ext\.?)\s+/, "")
    .split(/\s+-\s+/)[0]
    .replace(/\s+/g, " ")
    .trim();
}

const start = (beats: Beat[]) => beats[0].startSec;
const end = (beats: Beat[]) => beats[beats.length - 1].endSec;

/**
 * Splits a film into chunks that can be motion-planned in parallel. Cuts are made where the place
 * changes, because positions are reset there anyway, so nothing is lost by planning the two sides
 * independently. Long stays in one place are split evenly as a fallback. A film with no beats, or
 * one short enough, is a single chunk.
 */
export function planChunks(
  timeline: Beat[],
  durationSec: number,
  options: Partial<ChunkOptions> = {},
): Chunk[] {
  const maxBeats = Math.max(1, Math.floor(options.maxBeats ?? DEFAULT_CHUNK_OPTIONS.maxBeats));
  const maxChunks = Math.max(1, Math.floor(options.maxChunks ?? DEFAULT_CHUNK_OPTIONS.maxChunks));

  const beats = [...timeline].sort((a, b) => a.startSec - b.startSec);
  if (!beats.length) return [{ beatIds: [], startSec: 0, endSec: durationSec }];

  const places: Beat[][] = [];
  for (const beat of beats) {
    const last = places.at(-1);
    if (last && placeKey(last[0].location) === placeKey(beat.location)) last.push(beat);
    else places.push([beat]);
  }

  const parts: Beat[][] = places.flatMap((place) => {
    const count = Math.ceil(place.length / maxBeats);
    const size = Math.ceil(place.length / count);
    return Array.from({ length: count }, (_, i) => place.slice(i * size, (i + 1) * size)).filter((p) => p.length);
  });

  while (parts.length > maxChunks) {
    let best = 0;
    let bestSpan = Infinity;
    for (let i = 0; i < parts.length - 1; i++) {
      const span = end(parts[i + 1]) - start(parts[i]);
      if (span < bestSpan) {
        bestSpan = span;
        best = i;
      }
    }
    parts.splice(best, 2, [...parts[best], ...parts[best + 1]]);
  }

  return parts.map((part, i) => ({
    beatIds: part.map((b) => b.id),
    startSec: i === 0 ? 0 : start(part),
    endSec: i === parts.length - 1 ? Math.max(durationSec, end(part)) : end(part),
  }));
}
